\label{vp_hamel}
The following statements are equivalent:
	\begin{enumerate}
		\item[(i)] The map \(\phi\) extremizes the action functional
		\begin{align*}
		    \int_U L(\phi,\mathbf{d}\phi)\,\mathrm{d}s\,\mathrm{d}t,
		\end{align*}
		for all variations \(\delta\phi\) vanishing on \(\partial U\).

		\item[(ii)] The map \(\phi\) satisfies the Euler-Lagrange equations
		\begin{align*}
		  \frac{\partial}{\partial t}\frac{\partial L}{\partial\phi_t} + \frac{\partial}{\partial s}\frac{\partial L}{\partial\phi_s} - \frac{\partial L}{\partial\phi} = 0.
		\end{align*}

		\item[(iii)] The map \((\phi,\xi)\) extremizess the functional
		\begin{align*}
		  \int_U l(\phi,\xi)\,\mathrm{d}s\,\mathrm{d}t
		\end{align*}
		with respect to variations $\delta\xi$, induced by the variations $\delta\phi = \Psi_{\phi}\eta$, and given by $\delta\xi = \mathbf{d}\eta + [\xi,\eta]_{\phi}$, where $\eta: U\rightarrow V$ vanishes on $\partial U$. 

		\item[(iv)] The map $(\phi,\xi)$ satisfies field-theoretic Hamel's equations
		\begin{align*}
		\frac{\partial}{\partial t}\frac{\partial l}{\partial\zeta}
		+ \frac{\partial}{\partial s}\frac{\partial l}{\partial\gamma}
		- \left[\zeta,\frac{\partial l}{\partial\zeta}\right]_{\phi}^{*}
		- \left[\gamma,\frac{\partial l}{\partial\gamma}\right]_{\phi}^{*}
		- \Psi_{\phi}^{*}\frac{\partial l}{\partial\phi} = 0
		\end{align*}
		coupled with the kinematic equation $\mathbf{d}\phi = \Psi_{\phi}\xi$.
	\end{enumerate}

Consider the linear wave equation, with state  $\phi\in\mathbb{R}$, $t\in\mathbb{R}$ being the temporal variable and $s\in[0,S]$ being the spatial variable. The covariant configuration bundle is therefore $\pi_{BE}: B\times G\rightarrow B$, where the base space $B=\mathbb{R}\times[0,S]$ and the fiber $G=\mathbb{R}$. The Lagrangian of the wave motion is the kinetic energy minus the potential energy
\begin{equation}
\ell(g,\zeta,\gamma) = \frac{1}{2}\left(\zeta^{2} - \gamma^{2}\right).
\label{L_1}
\end{equation}
Similar to the geometrically exact beam, the fiber of this system is also a Lie group, but the trivial one $Q=\mathbb{R}$. By selecting moving frames to be the identity map $T_{e}L_{\phi} = \mathrm{Id}_{\mathbb{R}}$, the operators $\mathrm{ad}$ and $\mathrm{ad}^{*}$ are trivial, that is, $\mathrm{ad}_{\zeta} = 0$ and $\mathrm{ad}^{*}_{\zeta} = 0$. Hence, the stochastic equations of motion \eqref{sto_Hamel}-\eqref{sto_com} for the wave system read
\begin{equation}
\begin{aligned}
d_{t}\zeta &= \gamma_{s}dt, \\
d_{t}\phi &= \zeta dt + \Theta\circ dW,  \\
\phi_{s} &= \gamma,  \\
d_{t}\gamma &= \zeta_{s}dt + \Theta_{s}\circ dW,
\label{wave1}
\end{aligned}
\end{equation}
where $\Theta: \mathbb{R}\times[0,S]\rightarrow\mathbb{R}$ is the diffusivity vector field, and $(\cdot)_{s} = \partial/\partial s$ represents taking the spatial derivative. If $\Theta$ is chosen to be zero, the above equations \eqref{wave1} specialize to
\begin{align*}
\zeta_{t} = \gamma_{s}, 
\quad
\phi_{t} = \zeta, 
\quad
\phi_{s} = \gamma, 
\quad
\gamma_{t} = \zeta_{s},
\end{align*}
which recovers the deterministic wave equation $\left(-\frac{\partial^{2}}{\partial t^{2}} + \triangle\right)\phi = 0$ in \cite{evans2022partial}.

\label{equi_continuous}
The first and the second way of introducing the stochasticity are closely related. By comparing the coefficients, one observes that \eqref{sto_Hamel}-\eqref{sto_com} and \eqref{e8}-\eqref{e9} are equivalent if and only if
\begin{align}
\frac{\delta\Phi}{\delta\mu}(g,\mu) = \Theta
\qquad
\text{and}
\qquad
T_{e}^{*}L_{g}\frac{\delta\Phi}{\delta g}(g,\mu) = 0,
\label{equivalence}
\end{align}
which is equivalent to that the stochastic potential is of the following form
\begin{align*}
\Phi(g,\mu) = \left<\mu,\Theta\right> + C,
\label{equivalence}
\end{align*}
where $C\in\mathbb{R}$ is a constant.

\label{ene_evo}
The following two statements are equivalent:
\begin{itemize}
  \item[(a)] The equations of motion are given by \eqref{sto_Hamel_Ham}-\eqref{sto_com_Ham} in the stochastic Hamiltonian form;
  \item[(b)] For any smooth function $f$, its dynamics can be given in the following \textit{Stratonovich-Lie-Poisson} form
    \begin{equation}
    d_{t}f = \left\{f,h\right\}dt + \left\{f,\Phi\right\}\circ dW,
    \label{SLP}
    \end{equation}
    where the affine Lie-Poisson bracket $\left\{\cdot,\cdot\right\}$ is given by Lemma~\ref{ChenShi2025}.
\end{itemize}

\label{Choice_Phi}
There are some specific choices of $\Phi$ such that the energy is conserved. (a) A trivial situation occurs when $\Phi$ is a Casimir function \citep{marsden1999}, which Poisson-commutes with $\mu$ and $\gamma$ and therefore makes the equations of motion implicitly stochastic according to \eqref{SLP}. (b) Other interesting but nontrivial candidates of $\Phi$ that conserve energy include smooth functions of the Hamiltonian $h$ (that is, $\Phi = \Psi(h)$, where $\Psi$ is a differentiable function), then the affine Lie-Poisson bracket $\left\{h,\Phi\right\}
= D\Psi(h)\left\{h, h\right\}
= 0$, which implies that the total energy is conserved.

\label{exact_variations}
The exact variations $\delta\zeta^{n+1/2}_{j}$ and $\delta\gamma^{n}_{j+1/2}$ subject to constraints \eqref{dis_kin_eq} and \eqref{dis_spatial_equation} are given by
\begin{eqnarray}
\delta\zeta^{n+1/2}_{j} \Delta t 
&=& \delta\left(\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)\right)  
= \mathrm{d}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)}\tau^{-1}
\cdot
\left(
-\eta^{n}_{j} + \mathrm{Ad}_{\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}}\eta^{n+1}_{j}
\right),  \label{var_zeta_2}\\
\delta\gamma^{n}_{j+1/2} \Delta s&=& 
\delta\left(\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)\right)
=
\mathrm{d}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)}\tau^{-1}
\cdot
\left(
-\eta^{n}_{j} + \mathrm{Ad}_{\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}}\eta^{n}_{j+1}
\right),
\label{var_gamma_2}
\end{eqnarray}
where $\eta^{n}_{j} = \left(g^{n}_{j}\right)^{-1}\delta g^{n}_{j}$, 
$\mathrm{Ad}:G\times\mathfrak{g}\rightarrow\mathfrak{g}$ is the adjoint action, and $\mathrm{d}\tau^{-1}:\mathfrak{g}\times\mathfrak{g}\rightarrow\mathfrak{g}$ is the inverse right trivialized tangent \citep{Bou_Rabee_Marsden_2009}.

\label{theorem_exact_integrator}
The following statements are equivalent:
\begin{itemize}
    \item[(i)] The discrete curve
    \begin{equation*}
    c_{d} =
    \left\{
    \left(g^{0}_{j},\zeta^{1/2}_{j},\gamma^{0}_{j+1/2},g^{1}_{j},\cdots,g^{N-1}_{j},\zeta^{N-1/2}_{j},\gamma^{N-1}_{j+1/2},g^{N}_{j}\right)
    \right\}
    \end{equation*}
    in $C_{d}(N,J) = \left(G\times\left(\mathfrak{g}\oplus \mathfrak{g}\times G\right)^{N}\right)^{J}$ with kinematics constraints \eqref{dis_kin_eq}-\eqref{dis_spatial_equation} is a critical point of the stochastic action sum \eqref{discrete_act_sum_1}, that is, 
    $$\delta A_{d} = 0,$$
    for variations $\delta g^{n}_{j}$, $\delta\zeta^{n+1/2}_{j}$, and $\delta\gamma^{n}_{j+1/2}$ given by Prop.~\ref{exact_variations}
    and the fixed point condition $\delta g^{0}_{j} = \delta g^{N}_{j} = 0$, $j=1,\dots,J$.
    \item[(ii)] The discrete curve
    \begin{equation*}
    c_{d} =
    \left\{
    \left(g^{0}_{j},\zeta^{1/2}_{j},\gamma^{0}_{j+1/2},g^{1}_{j},\cdots,g^{N-1}_{j},\zeta^{N-1/2}_{j},\gamma^{N-1}_{j+1/2},g^{N}_{j}\right)
    \right\}
    \end{equation*}
    subject to constraints \eqref{dis_kin_eq}-\eqref{dis_spatial_equation} satisfies the discrete stochastic equations of motion
    \begin{eqnarray}
    \begin{aligned}
    &\Delta t\Delta s T_{e}^{\ast}L_{g^{n}_{j}}\frac{\delta\ell}{\delta g}\left(g^{n}_{j},\zeta^{n+1/2}_{j},\gamma^{n}_{j+1/2}\right)
    - \Delta s\left[\mathrm{d_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)}\tau^{-1}}\right]^{\ast}
    \frac{\delta\ell}{\delta\zeta}\left(g^{n}_{j},\zeta^{n+1/2}_{j},\gamma^{n}_{j+1/2}\right)  \\
    &\quad
    + \Delta s\mathrm{Ad}^{\ast}_{\left(g^{n-1}_{j}\right)^{-1}g^{n}_{j}}
    \left[\mathrm{d_{\tau^{-1}\left(\left(g^{n-1}_{j}\right)^{-1}g^{n}_{j}\right)}\tau^{-1}}\right]^{\ast}
    \frac{\delta\ell}{\delta\zeta}\left(g^{n-1}_{j},\zeta^{n-1/2}_{j},\gamma^{n-1}_{j+1/2}\right)  \\
    &\quad 
    + \Delta t\mathrm{Ad}^{\ast}_{\left(g^{n}_{j-1}\right)^{-1}g^{n}_{j}}
    \left[\mathrm{d_{\tau^{-1}\left(\left(g^{n}_{j-1}\right)^{-1}g^{n}_{j}\right)}\tau^{-1}}\right]^{\ast}
    \frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j-1},\zeta^{n+1/2}_{j-1},\gamma^{n}_{j-1/2}\right)  \\
    &\quad
    - \Delta t\left[\mathrm{d_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)}\tau^{-1}}\right]^{\ast}
    \frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j},\zeta^{n+1/2}_{j},\gamma^{n}_{j+1/2}\right) = 0,
    \label{without_truncation_exact}
    \end{aligned}
    \end{eqnarray}
    and the boundary conditions
    \begin{equation}
    \begin{aligned}    \left[\mathrm{d}_{\tau^{-1}\left(\left(g^{n}_{0}\right)^{-1}g^{n}_{1}\right)}\tau^{-1}\right]^{*}
    \frac{\delta\ell}{\delta\gamma^{n}_{1/2}} = 0
    \quad
    \text{and}
    \quad
    \mathrm{Ad}^{*}_{\left(g^{n}_{J-1}\right)^{-1}g^{n}_{J}}\left[\mathrm{d}_{\tau^{-1}\left(\left(g^{n}_{J-1}\right)^{-1}g^{n}_{J}\right)}\tau^{-1}\right]^{*}
    \frac{\delta\ell}{\delta\gamma^{n}_{J-1/2}} = 0.
    \label{Exact_bc}
    \end{aligned}
    \end{equation}
\end{itemize}

\label{app_var_formulae}
The exact variation formulae \eqref{var_zeta_2} and \eqref{var_gamma_2} admit series expansions
\begin{equation}
\begin{aligned}
\delta \left[\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)\right]
&= \delta\zeta^{n+1/2}_{j}\Delta t 
= \eta^{n+1}_{j} - \eta^{n}_{j}
+ \mathrm{ad}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)}\eta^{n+1/2}_{j}
+ \mathcal{O}\left(\Delta t^{3/2}\right),  \\
\delta \left[\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)\right]
&= \delta\gamma^{n}_{j+1/2}\Delta s 
= \eta^{n}_{j+1} - \eta^{n}_{j} + \mathrm{ad}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)}\eta^{n}_{j+1/2}
+ \mathcal{O}\left(\Delta s^{2}\right).
\label{approximate_variation_for}
\end{aligned}
\end{equation}

\label{Theorem_App_Int}
The approximate variation formulae \eqref{app_variation_formula_1} induce a stochastic variational integrator
\begin{equation}
\begin{aligned}
&\Delta t\Delta s T_{e}^{\ast}L_{g^{n}_{j}}\frac{\delta\ell}{\delta g}\left(g^{n}_{j},\zeta^{n+\frac{1}{2}}_{j},\gamma^{n}_{j+\frac{1}{2}}\right)
- \Delta s
\frac{\delta\ell}{\delta\zeta}\left(g^{n}_{j},\zeta^{n+\frac{1}{2}}_{j},\gamma^{n}_{j+\frac{1}{2}}\right)
+ \frac{\Delta s}{2}\mathrm{ad}^{\ast}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)}
\frac{\delta\ell}{\delta\zeta}\left(g^{n}_{j},\zeta^{n+\frac{1}{2}}_{j},\gamma^{n}_{j+\frac{1}{2}}\right)\\
&\quad
+ \Delta s\frac{\delta\ell}{\delta\zeta}\left(g^{n-1}_{j},\zeta^{n-1/2}_{j},\gamma^{n-1}_{j+1/2}\right)
+ \frac{\Delta s}{2}\mathrm{ad}^{\ast}_{\tau^{-1}\left(\left(g^{n-1}_{j}\right)^{-1}g^{n}_{j}\right)}\frac{\delta\ell}{\delta\zeta}\left(g^{n-1}_{j},\zeta^{n-1/2}_{j},\gamma^{n-1}_{j+1/2}\right)  \\
&\quad
- \Delta t\frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j},\zeta^{n+1/2}_{j},\gamma^{n}_{j+1/2}\right)
+ \frac{\Delta t}{2}\mathrm{ad}^{\ast}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)}
\frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j},\zeta^{n+1/2}_{j},\gamma^{n}_{j+1/2}\right)  \\
&\quad 
+ \Delta t\frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j-1},\zeta^{n+1/2}_{j-1},\gamma^{n}_{j-1/2}\right)
+ \frac{\Delta t}{2}\mathrm{ad}^{\ast}_{\tau^{-1}\left(\left(g^{n}_{j-1}\right)^{-1}g^{n}_{j}\right)}\frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j-1},\zeta^{n+1/2}_{j-1},\gamma^{n}_{j-1/2}\right)
= 0,
\label{App_Integrator_1}
\end{aligned}
\end{equation}
together with the discrete stochastic boundary condition
\begin{equation}
\begin{aligned}
&- \frac{\delta\ell}{\delta\gamma}
\left(
g^{n}_{0},\zeta^{n+1/2}_{0},\gamma^{n}_{1/2}
\right)
+
\frac{1}{2}
\mathrm{ad}^{*}_{
\tau^{-1}\left(\left(g^{n}_{0}\right)^{-1}g^{n}_{1}\right)
}
\frac{\delta\ell}{\delta\gamma}\left(g^{n}_{0},\zeta^{n+1/2}_{0},\gamma^{n}_{1/2}\right) = 0,  \\
&\frac{\delta\ell}{\delta\gamma}
\left(
g^{n}_{J-1},\zeta^{n+1/2}_{J-1},\gamma^{n}_{J-1/2}
\right)
+ \frac{1}{2}
\mathrm{ad}^{*}_{
\tau^{-1}\left(\left(g^{n}_{J-1}\right)^{-1}g^{n}_{J}\right)
}
\frac{\delta\ell}{\delta\gamma}\left(g^{n}_{J-1},\zeta^{n+1/2}_{J-1},\gamma^{n}_{J-1/2}\right)
= 0.
\label{App_boun_con_1}
\end{aligned}
\end{equation}

\label{Exam_wave}
For the stochastic wave motion, the discrete action sum associated to \eqref{L_1} is
\begin{equation*}
A_{d} = 
\sum_{n=0}^{N-1}\sum_{j=0}^{J-1}
\frac{\Delta t\Delta s}{2}
\left[
\left(\zeta^{n+1/2}_{j}\right)^{2}
-
\left(\gamma^{n}_{j+1/2}\right)^{2}
\right].
\end{equation*}
Then, the Type-I stochastic integrator given by \eqref{dis_kin_eq}, \eqref{dis_spatial_equation}, \eqref{App_Integrator_1}, and \eqref{d_sto_compatibility} reads
\begin{equation}
\begin{aligned}
&
\Delta s\left(\zeta^{n-1/2}_{j} - \zeta^{n+1/2}_{j}\right)
-
\Delta t\left(\gamma^{n}_{j-1/2} - \gamma^{n}_{j+1/2}\right)
= 0, \\
&
\Delta s\left(\gamma^{n+1}_{j+\frac{1}{2}} - \gamma^{n}_{j+\frac{1}{2}}\right)
- \Delta t\left(\zeta^{n+\frac{1}{2}}_{j+1} - \zeta^{n+\frac{1}{2}}_{j}\right) 
+ \Theta^{n+\frac{1}{2}}_{j}
\left(W^{(M)}_{n+1,j} - W^{(M)}_{n,j}\right)
-  \Theta^{n+\frac{1}{2}}_{j+1}
\left(W^{(M)}_{n+1,j+1} - W^{(M)}_{n,j+1}\right)
= 0, \\
&
\phi^{n+1}_{j} - \phi^{n}_{j}
-
\Delta t \zeta^{n+1/2}_{j}
-
\Theta^{n+1/2}_{j}
\left(
W^{(M)}_{n+1,j} - W^{(M)}_{n,j}
\right)
= 0, \\
&\phi^{n}_{j+1} - \phi^{n}_{j}
-
\Delta s\gamma^{n}_{j+1/2}
= 0, \\
& \gamma^{n}_{1/2} = \gamma^{n}_{J+1/2} = 0,
\label{e11}
\end{aligned}
\end{equation}
which is a stochastic deformation of the deterministic staggered leapfrog scheme for the wave equation \citep{MoMa2005}. Moreover, if one interprets $\zeta$ and $\gamma$ as the electric and magnetic flux densities, respectively, equations \eqref{e11} become a stochastic extension of the well-known Yee's scheme \citep{Yee1966} in computational electromagnetism for the stochastic fields that depend on a single spatial variable.

Moreover, in this trivial Lie group case, the operations $\mathrm{Ad}^{*}$ and $\left[\mathrm{d}\tau^{-1}\right]^{*}$ specialize to identity maps and the adjoint action $\mathrm{ad}$ vanishes, which implies that the exact variation \eqref{var_zeta_2}-\eqref{var_gamma_2} are the same as the approximate variation formulae \eqref{app_variation_formula_1}. Thus, the approximate integrator \eqref{App_Integrator_1} coincides with the exact integrator \eqref{without_truncation_exact} in this case.

For the stochastic geometrically exact beam, the discrete action sum reads
\begin{equation*}
A_{d} = \sum_{n=0}^{N-1}\sum_{j=0}^{J-1}\Delta t\Delta s
\ell\left(g^{n}_{j},\zeta^{n+1/2}_{j},\gamma^{n}_{j+1/2}\right),
\end{equation*}
where $g^{n}_{j}\in SE(3)$ and $\zeta^{n+1/2}, \gamma^{n}_{j+1/2}\in\mathfrak{se}(3)$. The resulting Type-I approximate integrator reads
\begin{align*}
&\Delta s
\left(
\mathcal{K}\zeta^{n-\frac{1}{2}}_{j} - \mathcal{K}\zeta^{n+\frac{1}{2}}_{j}
\right)
-
\Delta t
\left(
\mathcal{P}\gamma^{n}_{j-\frac{1}{2}}
-
\mathcal{P}\gamma^{n}_{j+\frac{1}{2}}
\right)  
-
\frac{\Delta t}{2}
\mathrm{ad}^{*}_{
\Delta s\gamma^{n}_{j+\frac{1}{2}}
}
\mathcal{P}\gamma^{n}_{j+\frac{1}{2}}
-
\frac{\Delta t}{2}
\mathrm{ad}^{*}_{
\Delta s\gamma^{n}_{j-\frac{1}{2}}
}
\mathcal{P}\gamma^{n}_{j-\frac{1}{2}}  \\
& 
+
\frac{\Delta s}{2}
\mathrm{ad}^{*}_{
\Delta t\zeta^{n+\frac{1}{2}}_{j} 
+ 
\Theta^{n+\frac{1}{2}}_{j}
\left(W^{(M)}_{n+1,j} - W^{(M)}_{n,j}\right)
}
\mathcal{K}\zeta^{n+\frac{1}{2}}_{j}
+
\frac{\Delta s}{2}
\mathrm{ad}^{*}_{
\Delta t\zeta^{n-\frac{1}{2}}_{j} 
+ 
\Theta^{n-\frac{1}{2}}_{j}
\left(W^{(M)}_{n,j} - W^{(M)}_{n-1,j}\right)
}
\mathcal{K}\zeta^{n-\frac{1}{2}}_{j}
= 0,
\end{align*}
together with the discrete stochastic compatibility condition
\begin{align*}
&\Delta s\left(\gamma^{n+1}_{j+1/2} - \gamma^{n}_{j+1/2}\right)
- \Delta t\left(\zeta^{n+1/2}_{j+1} - \zeta^{n+1/2}_{j}\right) 
+ \Theta^{n+1/2}_{j}
\left(W^{(M)}_{n+1,j} - W^{(M)}_{n,j}\right)
-  \Theta^{n+1/2}_{j+1}
\left(W^{(M)}_{n+1,j+1} - W^{(M)}_{n,j+1}\right)  \\
&= \frac{1}{2}
\left[
\Delta s\gamma^{n+1}_{j+1/2},
\Delta t\zeta^{n+1/2}_{j} + \Theta^{n+1/2}_{j}
\left(W^{(M)}_{n+1,j} - W^{(M)}_{n,j}\right)
\right]  \\
&\qquad
+ \frac{1}{2}
\left[
\Delta s\gamma^{n}_{j+1/2},
\Delta t\zeta^{n+1/2}_{j+1} + \Theta^{n+1/2}_{j+1}
\left(W^{(M)}_{n+1,j+1} - W^{(M)}_{n,j+1}\right)
\right].
\end{align*}

\label{Theorem_Type_II}
The following statements are equivalent:
\begin{itemize}
    \item [(i)] The discrete stochastic curve
\begin{equation}
c_{d} =
\left\{
\left(g^{0}_{j},\zeta^{1/2}_{j},\mu^{1/2}_{j},\gamma^{0}_{j+1/2},\sigma^{0}_{j+1/2},g^{1}_{j},\cdots,g^{N-1}_{j},\zeta^{N-1/2}_{j},\mu^{N-1/2}_{j},\gamma^{N-1}_{j+1/2},\sigma^{N-1}_{j+1/2},g^{N}_{j}\right)
\right\}
\label{dis_sto_curve_hp}
\end{equation}
satisfies the following discrete stochastic equations:
\begin{numcases}{}
\diamond\hspace{0.2em}\text{\sc Discrete stochastic temporal kinematic equation:} & \label{dis_tem_eqn_2}\hfill\\
\quad \delta\mu^{n+1/2}_{j}: \tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)
- \Delta t\zeta^{n+1/2}_{j}
- \frac{\delta\Phi}{\delta\mu}\left(g^{n}_{j}, \mu^{n+1/2}_{j}\right)
\left(
W^{(M)}_{n+1,j} - W^{(M)}_{n,j}
 \right) = 0, & \notag\hfill\\
\diamond\hspace{0.2em}\text{\sc Discrete stochastic spatial kinematic equation:} & \hfill\\
\quad \delta\sigma^{n}_{j+1/2}: \tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)
- \Delta s\gamma^{n}_{j+1/2} = 0, & \notag\hfill\\
\diamond\hspace{0.2em}\text{\sc Discrete stochastic temporal Legendre transform:} & \label{leg_tem} \hfill\\
\quad \delta \zeta^{n+1/2}_{j}: \mu^{n+1/2}_{j} = \frac{\delta\ell}{\delta\zeta}\left(g^{n}_{j}, \zeta^{n+1/2}_{j}, \gamma^{n}_{j+1/2}\right), &   \notag\hfill\\
\diamond\hspace{0.2em}\text{\sc Discrete stochastic spatial Legendre transform:} & \label{leg_spa}\hfill\\
\quad \delta \gamma^{n}_{j+1/2}: \sigma^{n}_{j+1/2} = \frac{\delta\ell}{\delta\gamma}\left(g^{n}_{j}, \zeta^{n+1/2}_{j}, \gamma^{n}_{j+1/2}\right), &  \notag\hfill\\
\diamond\hspace{0.2em}\text{\sc Discrete stochastic implicit field-theoretic equation:} & \label{imp_ham}\hfill\\
\quad \eta^{n}_{j}: \Delta s\left(\mu^{n-1/2}_{j} - \mu^{n+1/2}_{j}\right)
+ \Delta t\left(\sigma^{n}_{j-1/2} - \sigma^{n}_{j+1/2}\right)  & \notag\hfill\\
\qquad\quad
+ \frac{\Delta s}{2}
\mathrm{ad}^{*}_{
\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)
}\mu^{n+1/2}_{j}
+ \frac{\Delta s}{2}
\mathrm{ad}^{*}_{
\tau^{-1}\left(\left(g^{n-1}_{j}\right)^{-1}g^{n}_{j}\right)
}\mu^{n-1/2}_{j}  &  \notag\hfill  \\
\qquad\quad
+ \frac{\Delta t}{2}
\mathrm{ad}^{*}_{
\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)
}\sigma^{n}_{j+1/2}
+ \frac{\Delta t}{2}
\mathrm{ad}^{*}_{
\tau^{-1}\left(\left(g^{n}_{j-1}\right)^{-1}g^{n}_{j}\right)
}\sigma^{n}_{j-1/2}  & \notag\hfill\\
\qquad\quad
- \Delta s T_{e}L^{\ast}_{g^{n}_{j}}
\frac{\delta\Phi}{\delta g}\left(g^{n}_{j}, \mu^{n+1/2}_{j}\right)
\left(
W^{(M)}_{n+1,j} - W^{(M)}_{n,j}
\right)
+ \Delta t\Delta s T_{e}L^{\ast}_{g^{n}_{j}}
\frac{\delta\ell}{\delta g}\left(g^{n}_{j}, \zeta^{n+1/2}_{j}, \gamma^{n}_{j+1/2}\right)
