Recall that the adjoint action map admits a series expansion \citep{hall2015lie}
\begin{equation*}
\mathrm{Ad}_{\tau(X)} = I + \mathrm{ad}_{X} + \frac{1}{2}\mathrm{ad}^{2}_{X} + \mathcal{O}(|X|^{3}),
\end{equation*}
where $\tau$ is the exponential map.
Thus, in the exact variation formula \eqref{var_zeta_2} the term
\begin{align*}
&-\eta^{n}_{j} + \mathrm{Ad}_{\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}}\eta^{n+1}_{j}  \\
&= -\eta^{n}_{j} + \mathrm{Ad}_{\tau\left(\Delta t\zeta^{n+1/2}_{j} + \Theta^{n+1/2}_{j}
\left(
W^{(M)}_{n+1,j} - W^{(M)}_{n,j}
\right)
\right)}\eta^{n+1}_{j}  \\
&= -\eta^{n}_{j} + \eta^{n+1}_{j} 
+ \mathrm{ad}_{\Delta t\zeta^{n+1/2}_{j} + \Theta^{n+1/2}_{j}
\left(
W^{(M)}_{n+1,j} - W^{(M)}_{n,j}
\right)}\eta^{n+1}_{j}
+ \frac{1}{2}\mathrm{ad}^{2}_{\Delta t\zeta^{n+1/2}_{j} + \Theta^{n+1/2}_{j}
\left(
W^{(M)}_{n+1,j} - W^{(M)}_{n,j}
\right)}\eta^{n+1}_{j}
+ \mathcal{O}\left(\Delta t^{3/2}\right),
\end{align*}
where the first equality uses \eqref{dis_kin_eq}. On the other hand, since the inverse right trivialized tangent admits an expansion \citep{Iserles2000lie,hairer2006,Bou_Rabee_Marsden_2009}
\begin{equation*}
\mathrm{d}_{X}\tau^{-1} = I - \frac{1}{2}\mathrm{ad}_{X} + \mathcal{O}\left(|X|^{2}\right),
\end{equation*} 
the exact variation formula \eqref{var_zeta_2} becomes
\begin{align*}
\delta \left[\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}\right)\right]
&= \delta\zeta^{n+1/2}_{j}\Delta t 
= \mathrm{d}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)}\tau^{-1}
\cdot
\left(
-\eta^{n}_{j} + \mathrm{Ad}_{\left(g^{n}_{j}\right)^{-1}g^{n+1}_{j}}\eta^{n+1}_{j}
\right)  \\
\nonumber &=: \mathrm{d}_{V}\tau^{-1}\cdot A  \\
\nonumber &= A - \frac{1}{2}\mathrm{ad}_{V}A + \mathcal{O}\left(\Delta t^{3/2}\right)  \\
\nonumber &= A - \frac{1}{2}\mathrm{ad}_{V}
\left(
- \eta^{n}_{j} + \eta^{n+1}_{j} + \mathrm{ad}_{V}\eta^{n+1}_{j}
\right)
+ \mathcal{O}(\Delta t^{3/2})  \\
&= \eta^{n+1}_{j} - \eta^{n}_{j} + \mathrm{ad}_{V}\eta^{n+1/2}_{j} + \mathcal{O}\left(\Delta t^{3/2}\right).
\label{d_tau_inv_2}
\end{align*}
Similarly, for the spatial part we have
\begin{align*}
\delta \left[\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)\right] 
&= 
\delta\gamma^{n}_{j+1/2}\Delta s
=
\mathrm{d}_{\tau^{-1}\left(\left(g^{n}_{j}\right)^{-1}g^{n}_{j+1}\right)}\tau^{-1}
\cdot
\left(
